import {makeKinematics,diagnostics,norm,sub,mm,transpose,rotationLog,rpyMatrix,matrixRpy} from './math.js';
import {PythonRunner} from './python-runner.js';

const $=id=>document.getElementById(id), deg=180/Math.PI, rad=Math.PI/180;
const presets={comfortable:[0,-90,90,-90,90,0],wrist_near:[0,-90,90,-90,.5,0],wrist:[0,-90,90,-90,0,0],elbow:[0,-65,0,-40,-70,15]};
const notes={comfortable:'A raised, well-conditioned start. Try the default solver, then change one line.',wrist_near:'Wrist 2 is 0.5°. The full-pose Jacobian is close to losing rank. Compare the gains and solver paths.',wrist:'Wrist 2 is exactly 0°. The full-pose Jacobian loses rank, but position control remains possible here.',elbow:'The elbow is straight. Compare full-pose and position-only ranks, then bend joint 3 slightly.'};
const draftKey='ur3-python-v1';
let model,forward,viewer,runner,templates,kernel,startQ,q,target,mode='pose',result=null,frame=0,busy=false,playing=false,playTimer,sweepTimer,toastTimer,runCount=0;
let loadedSource='',history=[];
const source=()=>$('code-editor').value;
const damping=()=>Number($('damping').value);
const scientific=x=>x===0?'0':Math.abs(x)<.001?x.toExponential(2):x.toFixed(3);
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3000);}
function status(id,text,kind=''){$(id).textContent=text;$(id).className='status '+kind;}
function lines(){$('line-numbers').textContent=source().split('\n').map((_,i)=>i+1).join('\n');$('line-numbers').scrollTop=$('code-editor').scrollTop;}
function saveDraft(){lines();try{localStorage.setItem(draftKey,source());$('draft-status').textContent='Draft saved in this browser';}catch{$('draft-status').textContent='Storage unavailable — download to keep your code';}}
function loadExample(){loadedSource=templates[$('example-select').value];$('code-editor').value=loadedSource;saveDraft();$('code-editor').scrollTop=0;lines();}
function syncTarget(){['x','y','z'].forEach((a,i)=>$('target-'+a).value=target.p[i].toFixed(5));matrixRpy(target.R).forEach((v,i)=>$('target-'+['roll','pitch','yaw'][i]).value=(v*deg).toFixed(3));}
function nearby(){const f=forward(startQ.map((v,i)=>Math.max(model.joints[i].lower,Math.min(model.joints[i].upper,v+[4,-4,5,3,-4,3][i]*rad))));target={p:f.p,R:f.R};syncTarget();}
function stopPlayback(){playing=false;clearTimeout(playTimer);$('play-motion').textContent='Replay ▶';}
function clearResult(){stopPlayback();result=null;frame=0;q=[...startQ];viewer?.setTrajectory(null);status('solver-status','Ready to run');$('run-summary').textContent='Run your code with this start, target and task. Repeated runs use the same starting pose.';plot('error-plot',[],190);plot('angle-plot',[],155);setBusy(false);}
function setBusy(value){busy=value;for(const id of ['run-code','load-example','pose-preset','task-mode','damping','use-as-target','nearby-target','far-target','example-select'])$(id).disabled=value;document.querySelectorAll('.joint-sliders input,.target-fields input').forEach(el=>el.disabled=value);['roll','pitch','yaw'].forEach(a=>$('target-'+a).disabled=value||mode==='position');$('stop-code').disabled=!value;for(const id of ['play-motion','step-motion','playback'])$(id).disabled=value||!result;}
function selectPreset(name){startQ=presets[name].map(v=>v*rad);clearResult();nearby();$('pose-note').textContent=notes[name];render();}
function buildJoints(){const names=['Shoulder pan','Shoulder lift','Elbow','Wrist 1','Wrist 2','Wrist 3'];model.joints.forEach((joint,i)=>{const box=document.createElement('div');box.className='joint-control';const label=document.createElement('label');label.htmlFor='joint-'+i;label.textContent=names[i];const output=document.createElement('output');output.id='joint-value-'+i;label.append(output);const input=document.createElement('input');input.id='joint-'+i;input.type='range';input.min=joint.lower*deg;input.max=joint.upper*deg;input.step=.1;input.addEventListener('input',()=>{startQ=[...q];startQ[i]=Number(input.value)*rad;clearResult();$('pose-preset').selectedIndex=-1;$('pose-note').textContent='Custom start. The target stays fixed while you move the joints.';render();});box.append(label,input);$('joint-sliders').append(box);});}
function svgElement(name,attrs={},text){const e=document.createElementNS('http://www.w3.org/2000/svg',name);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));if(text!==undefined)e.textContent=text;return e;}
function svgText(svg,x,y,text,attrs={}){svg.append(svgElement('text',{x,y,fill:'#71818b','font-size':10,...attrs},text));}
function spectrum(d){const svg=$('spectrum');svg.replaceChildren();const max=Math.max(d.s[0],1e-12);d.s.forEach((s,i)=>{const w=390/d.s.length,x=58+i*w,h=120*s/max;svg.append(svgElement('rect',{x,y:145-h,width:w-18,height:Math.max(1,h),rx:3,fill:i===d.s.length-1?'#d87a46':'#74a4bd'}));svgText(svg,x+(w-18)/2,164,'σ'+(i+1),{'text-anchor':'middle'});svgText(svg,x+(w-18)/2,Math.max(15,138-h),scientific(s),{'text-anchor':'middle','font-size':9});});svgText(svg,12,20,'σ');}
function plot(id,values,height,options={}){const svg=$(id);svg.replaceChildren();const width=id==='wrist-sweep'?480:560,left=48,right=width-16,top=19,bottom=height-30;if(!values.length){svgText(svg,width/2,height/2,'Run a solver to see the residual.',{'text-anchor':'middle'});return;}const logs=values.map(v=>Math.log10(Math.max(v,options.floor||1e-5)));let lo=Math.floor(Math.min(...logs)),hi=Math.ceil(Math.max(...logs));if(hi<=lo)hi=lo+1;const y=v=>bottom-(v-lo)/(hi-lo)*(bottom-top),x=i=>left+(right-left)*i/Math.max(1,values.length-1);for(let k=0;k<=4;k++){const v=lo+(hi-lo)*k/4;svg.append(svgElement('line',{x1:left,x2:right,y1:y(v),y2:y(v),stroke:'#e4ebef'}));svgText(svg,left-7,y(v)+3,'1e'+v.toFixed(v%1?1:0),{'text-anchor':'end','font-size':9});}svg.append(svgElement('polyline',{points:logs.map((v,i)=>`${x(i)},${y(v)}`).join(' '),fill:'none',stroke:options.color||'#347ba2','stroke-width':2}));if(values.length===1)svg.append(svgElement('circle',{cx:x(0),cy:y(logs[0]),r:3,fill:'#347ba2'}));svgText(svg,left,height-9,options.sweep?'−30°':'0');svgText(svg,right,height-9,options.sweep?'+30°':String(values.length-1),{'text-anchor':'end'});svgText(svg,(left+right)/2,height-9,options.sweep?'Wrist 2 (0° at centre)':'Recorded updates',{'text-anchor':'middle'});if(options.sweep){svg.append(svgElement('line',{x1:x((values.length-1)/2),x2:x((values.length-1)/2),y1:top,y2:bottom,stroke:'#d87a46','stroke-dasharray':'3 3'}));}else{const j=Math.min(frame,values.length-1);svg.append(svgElement('circle',{cx:x(j),cy:y(logs[j]),r:3.5,fill:'#d87a46'}));}}
function updateLens(f){const d=diagnostics(f,mode),p=mode==='position'?d:diagnostics(f,'position');const singular=d.ratio<=1e-7,near=d.ratio<.01;status('rank-status',singular?'Singular for this task':near?'Near a singularity':'Full task rank',singular?'singular':near?'near':'good');$('rank-value').textContent=`Rank ${d.rank} / ${d.s.length}`;$('position-rank').textContent=`${p.rank} / 3`;$('spectrum-title').textContent=mode==='pose'?'Scaled full-pose Jacobian':'Scaled position Jacobian';$('sigma-min').textContent=scientific(d.s.at(-1));$('condition-number').textContent=Number.isFinite(d.condition)?(d.condition<1000?d.condition.toFixed(1):d.condition.toExponential(2)):'∞';const s=d.s.at(-1);$('pinv-gain').textContent=s>d.s[0]*1e-6?scientific(1/s):'Discarded';$('dls-gain').textContent=scientific(s/(s*s+damping()**2));spectrum(d);$('singularity-explanation').textContent=(mode==='position'?'Position-only asks for three independent directions; the tool orientation is free. ':'Full pose asks for six independent directions: three linear and three angular. ')+(singular?'At this pose, at least one instantaneous task direction is missing. This does not mean every nearby target is impossible; a sequence of updates may leave the singularity. ':near?'A weak direction can amplify joint updates. Compare pseudoinverse and DLS while keeping the start and target fixed. ':'The selected task has full numerical rank here. This alone does not guarantee convergence to a distant target. ')+'“Near” means σmin / σmax < 0.01 in this exercise.';clearTimeout(sweepTimer);const snapshot=[...q],taskMode=mode;sweepTimer=setTimeout(()=>{const values=Array.from({length:61},(_,i)=>{const test=[...snapshot];test[4]=(i-30)*rad;return diagnostics(forward(test),taskMode).s.at(-1);});plot('wrist-sweep',values,185,{sweep:true,floor:1e-12,color:'#d87a46'});},90);}
function render(){const f=forward(q);$('position-error').textContent=(norm(sub(target.p,f.p))*1000).toFixed(3);$('orientation-error').textContent=(norm(rotationLog(mm(target.R,transpose(f.R))))*deg).toFixed(3);$('iteration-value').textContent=frame;$('frame-total').textContent='/ '+(result?.updates||0);$('frame-label').textContent=`${frame} / ${result?.updates||0}`;$('playback').max=result?.updates||0;$('playback').value=frame;model.joints.forEach((_,i)=>{$('joint-'+i).value=q[i]*deg;$('joint-value-'+i).textContent=(q[i]*deg).toFixed(1)+'°';});$('angle-label').textContent=mode==='pose'?'Full-pose task':'Not controlled in position-only mode';viewer?.update(q,target,'',frame);updateLens(f);if(result){plot('error-plot',result.errors.map(v=>v*1000),190);plot('angle-plot',result.angles.map(v=>v*deg),155);}}
function showFrame(i){if(!result)return;frame=Math.max(0,Math.min(result.updates,i));q=[...result.trajectory[frame]];render();}
function play(){if(playing){stopPlayback();return;}if(!result)return;if(frame>=result.updates)showFrame(0);playing=true;$('play-motion').textContent='Pause';const tick=()=>{if(!playing||!result)return;showFrame(frame+1);if(frame>=result.updates)stopPlayback();else playTimer=setTimeout(tick,Math.max(25,Math.min(250,2000/result.updates)));};playTimer=setTimeout(tick,250);}
function appendOutput(text){const out=$('python-output');out.textContent=(out.textContent+text+'\n').slice(-20000);out.scrollTop=out.scrollHeight;}
async function run(){if(busy)return;stopPlayback();const snapshot=source(),config={start:[...startQ],target:structuredClone(target),mode,damping:damping()};result=null;frame=0;q=[...startQ];viewer?.setTrajectory(null);plot('error-plot',[],190);plot('angle-plot',[],155);setBusy(true);render();$('python-output').textContent='';$('python-output').className='';status('solver-status','Running…');$('run-summary').textContent='Solving from the selected start pose…';try{result=await runner.run(snapshot,config);viewer?.setTrajectory(result.trajectory);showFrame(result.updates);status('solver-status',result.converged?'Target reached':'Residual remains',result.converged?'good':'near');$('runtime-status').textContent='Python ready. Edit your code and run again.';$('run-summary').textContent=`${result.updates} recorded updates · position ${(result.error*1000).toFixed(4)} mm · orientation ${(result.angle*deg).toFixed(4)}° · ${result.elapsed_ms.toFixed(0)} ms in Python. ${mode==='position'?'Orientation is not part of this task. ':''}${snapshot!==source()?'Results use the code as it was when you pressed Run. ':''}Replay shows solver iterations, not a timed robot command.`;appendOutput(`Measured result: ${result.converged?'target reached':'residual remains'}.\nPosition ${(result.error*1000).toFixed(6)} mm; orientation ${(result.angle*deg).toFixed(6)}°.\n${result.updates} recorded updates.`);history.unshift({number:++runCount,...result});history=history.slice(0,5);$('run-history').replaceChildren(...history.map(r=>{const tr=document.createElement('tr');[r.number,r.mode==='pose'?'Full pose':'Position',r.updates,(r.error*1000).toFixed(4)+' mm',(r.angle*deg).toFixed(4)+'°',r.converged?'Yes':'No'].forEach(value=>{const td=document.createElement('td');td.textContent=value;tr.append(td);});return tr;}));}catch(error){const stopped=error.message.startsWith('Stopped');status('solver-status',stopped?'Stopped':'Code error',stopped?'near':'error');$('runtime-status').textContent=stopped?'Ready to restart Python.':'Fix the code, then run again.';$('run-summary').textContent='No completed result from this run.';$('python-output').className='error';appendOutput(error.message);}finally{setBusy(false);}}
function download(){const config={start:startQ,target,mode,damping:damping()};const program=`# UR3 + Robotiq 2F-85 student export\n# Run locally with Python and NumPy installed.\n# Browser version: https://miguelaltamirano.github.io/ur3-ik-playground/\n${kernel}\n\nMODEL = json.loads(${JSON.stringify(JSON.stringify(model))})\nCONFIG = json.loads(${JSON.stringify(JSON.stringify(config))})\nSOURCE = ${JSON.stringify(source())}\n\nif __name__ == '__main__':\n    result = run_student(SOURCE, CONFIG, MODEL)\n    print(json.dumps({k:v for k,v in result.items() if k != 'trajectory'}, indent=2))\n`;const blob=new Blob([program],{type:'text/x-python'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ur3_student_solver.py';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Downloaded code, model and current start/target.');}
async function init(){const paths=['assets/robot/kinematics.json','python/dls.py','python/pseudoinverse.py','python/transpose.py','python/kernel.py'];const responses=await Promise.all(paths.map(async path=>{const r=await fetch(path,{cache:'no-cache'});if(!r.ok)throw Error('Could not load '+path);return r.text();}));model=JSON.parse(responses[0]);templates={dls:responses[1],pseudoinverse:responses[2],transpose:responses[3]};kernel=responses[4];forward=makeKinematics(model);runner=new PythonRunner(model,text=>$('runtime-status').textContent=text,appendOutput);buildJoints();loadedSource=templates.dls;let saved=null;try{saved=localStorage.getItem(draftKey) ?? localStorage.getItem('ur3-2f140-python-v1');}catch{}$('code-editor').value=saved??loadedSource;$('draft-status').textContent=saved===null?'Example loaded — edits save in this browser':'Restored your saved draft';lines();for(const id of ['code-editor','download-code'])$(id).disabled=false;selectPreset('comfortable');
  $('code-editor').addEventListener('input',saveDraft);$('code-editor').addEventListener('scroll',lines);$('code-editor').addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const editor=e.target;editor.setRangeText('    ',editor.selectionStart,editor.selectionEnd,'end');saveDraft();}if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();run();}});
  $('load-example').onclick=()=>{if(source()!==loadedSource)$('replace-dialog').showModal();else loadExample();};$('cancel-replace').onclick=()=>$('replace-dialog').close();$('confirm-replace').onclick=()=>{$('replace-dialog').close();loadExample();};$('download-code').onclick=download;$('run-code').onclick=run;$('stop-code').onclick=()=>runner.stop();$('clear-output').onclick=()=>$('python-output').textContent='';
  $('pose-preset').onchange=e=>selectPreset(e.target.value);$('task-mode').onchange=e=>{mode=e.target.value;clearResult();render();};$('damping').oninput=()=>{$('damping-value').textContent=damping().toFixed(3);updateLens(forward(q));};$('nearby-target').onclick=()=>{clearResult();nearby();render();};$('far-target').onclick=()=>{clearResult();target={p:[.95,.95,.9],R:forward(startQ).R};syncTarget();render();};$('use-as-target').onclick=()=>{const f=forward(q);target={p:f.p,R:f.R};clearResult();syncTarget();render();toast('Target captured. Move a joint to choose a different start.');};
  document.querySelectorAll('.target-fields input').forEach(input=>input.addEventListener('change',()=>{if(!Number.isFinite(input.valueAsNumber)||input.valueAsNumber<Number(input.min)||input.valueAsNumber>Number(input.max)){syncTarget();toast('Enter a number inside the displayed target interval.');return;}const p=['x','y','z'].map(a=>Number($('target-'+a).value)),rpy=['roll','pitch','yaw'].map(a=>Number($('target-'+a).value)*rad);target={p,R:rpyMatrix(rpy)};clearResult();render();}));$('play-motion').onclick=play;$('step-motion').onclick=()=>{stopPlayback();showFrame(frame>=result.updates?0:frame+1);};$('playback').oninput=e=>{stopPlayback();showFrame(Number(e.target.value));};
  try{const {createViewer}=await import('./viewer.js?v=2f85-1');viewer=await createViewer($('robot-canvas'),model);$('viewer-loading').hidden=true;$('robot-canvas').dataset.ready='true';['focus-btn','camera-reset','zoom-in','zoom-out','show-frames','show-ellipsoid'].forEach(id=>$(id).disabled=false);$('focus-btn').onclick=()=>{$('focus-btn').textContent=viewer.focus()?'Whole robot':'Focus tool';};$('camera-reset').onclick=()=>{viewer.reset();$('focus-btn').textContent='Focus tool';};$('zoom-in').onclick=()=>viewer.zoom(.85);$('zoom-out').onclick=()=>viewer.zoom(1.18);$('show-frames').onchange=e=>viewer.setFrames(e.target.checked);$('show-ellipsoid').onchange=e=>viewer.setEllipsoid(e.target.checked);if(result)viewer.setTrajectory(result.trajectory);render();}catch(error){$('viewer-loading').textContent='3D view unavailable. Enable WebGL 2 or try another browser. The Python editor and plots still work.';console.warn(error);}
}
init().catch(error=>{$('boot-error').hidden=false;$('boot-error').textContent='The lab could not load. Check your connection and reload. '+error.message;});
